Using Recursion - O(N²) Time and O(N) SpaceIn this approach, recursion is used to print spaces and stars for each row of the diamond. Separate recursive functions print blank spaces, stars, the upper half, and the lower half of the diamond.
            C++

    //Driver Code Starts
using namespace std;

//Driver Code Ends

// Function to print stars in a line of the diamond
void gotonextLine(int k, int i, int z)
{

    // base case
    if (k == i)
        return;
    cout << "* ";
    gotonextLine(k + z, i, z);
}
void addblankSpaceInDiamond(

    // print blank space of diamond
    int j, int i, int z)
{
    if (j == i)
        return;
    cout << " ";
    addblankSpaceInDiamond(j + z, i, z);
}
void upperDiamond(int row, int i)
{
    // base case
    if (i > row)
        return;
    addblankSpaceInDiamond(row, i, -1);
    gotonextLine(0, i, 1);
    cout << endl;

    // recursive call
    upperDiamond(row, i + 1);
}
void lowerDiamond(int row, int i)
{
    // base case
    if (i > row)
        return;
    addblankSpaceInDiamond(0, i, 1);
    gotonextLine(row, i, -1);
    cout << endl;
    lowerDiamond(row, i + 1);
}

//Driver Code Starts
int main()
{
    int row;
    row = 5;

    // print upper part of triangle
    upperDiamond(row, 0);

    // print lower part of diamond
    lowerDiamond(row, 0);
    return 0;
}
